INSERT INTO `archived_documents` (`archived_id`, `team_id`, `title`, `abstract`, `authors`, `embedding`, `embedding_generated_at`, `academic_year`, `program`, `file_name`, `file_path`, `file_size`, `submitted_by`, `submitted_at`, `submission_status`) VALUES
(11, NULL, 'CPAG: CULTURAL AND PERFORMING ARTS GROUP MANAGEMENT SYSTEM WITH INCENTIVE MONITORING FOR CAMARINES SUR POLYTECHNIC COLLEGES (CSPC)', 'Educational institutions face significant challenges in managing cultural and performing arts programs where manual processes lead to operational inefficiencies, data loss, and accountability issues. At Camarines Sur Polytechnic Colleges (CSPC), the Cultural Affairs Office struggled with paper-based member applications, unreliable attendance tracking, inconsistent performance evaluations, inadequate inventory management, and labor-intensive incentive computations, resulting in administrative delays and difficulty monitoring student participation. This study aimed to develop a web-based Cultural and Performing Arts Group Management System with Incentive Monitoring (CPAG) that automates core operations through eight integrated modules: User Management, Member Application, Attendance Monitoring, Inventory Management, Incentive Management, Notification and Messaging, Reports and Analytics, and Event Management. The system was developed using Agile Extreme Programming (XP) methodology with CodeIgniter 4 framework and MySQL database, integrating DigitalPersona U.are.U 4500 fingerprint scanners for biometric attendance. Black box testing was conducted with 582 respondents comprising student performers, applicants, trainers, officers, administrators, and IT experts. Results demonstrated exceptional performance: Unit Testing achieved 0.99 (Highly Functional), User Acceptance Testing scored 0.99 (Highly Acceptable), Usability Testing obtained 1.00 (Highly Usable), and Security Testing using OWASP ZAP v2.16.1 yielded 0.98 (Highly Secure). All modules met functional requirements with scores ranging from 0.98 to 1.00. The CPAG system successfully transformed cultural group management at CSPC by eliminating paperwork, ensuring accurate attendance tracking through fingerprint biometrics, automating transparent incentive distribution, and providing real-time data access. Future enhancements include mobile application development and SMS notification integration.', 'Jason F. Balingasa, Jeorge N. Fabillar, Leslie C. Llaban, Renier John L. Vargas', '[-0.9497756958007812, 1.0535824298858645, -3.725815773010254, -0.4260214269161224, -0.10484962910413742, -0.1253250688314438, 1.7012611627578735, 0.7549526691436768, 0.9059705138206482, 0.4601514935493469, -0.29556500911712646, -0.16844555735588074, 1.4452741146087646, 0.7442398071289062, 1.0783644914627075, -0.9244592189788818, -0.8126129508018494, 0.3187658190727234, -1.436283826828003, 0.9381146430969238, 0.20679907500743863, -0.7600253224372864, -0.284740686416626, -0.3271001875400543, 1.7784643173217771, 0.7221806645393372, -0.41214171051979065, -0.5616188049316406, 0.0999208390712738, 0.5535458326339722, 0.10732953995466232, 0.2152116894721985, -0.622807502746582, -0.6180031299591064, -0.24211236834526065, -0.8299056887626648, 0.5887881517410278, 0.09250885248184204, 0.10528527945280076, 0.8835543394088745, 0.6492105722427368, -0.2746162712574005, -0.1701747328042984, -0.4169918894767761, 0.32948634028434753, -0.08727006614208221, 1.0799614191055298, -0.4982378482818603, 1.0821900367736816, -0.44916242361068726, 0.12009736895561218, -0.6989578008651733, 0.16446217894554138, 0.6753526926040649, 0.509101152420044, 0.28894275426864624, -0.41368407011032104, 0.2986173629760742, -0.165225088596344, -0.9586818814277648, 2.3221888542175293, 1.5847309827804563, -1.2535066604614258, 1.144822597503662, 0.5339019298553467, -0.5134215354919434, -0.08802527189254761, 0.5202299356460571, -0.1273505836725235, -1.2757558822631836, -0.30881693959236145, 0.33110183477401733, 0.3519022464752197, 0.215860515832901, -0.0999828353524208, -0.3227904736995697, -0.9218747615814208, -0.4471589922904968, -0.5321216583251953, 0.460670530796051, 0.7674039602279663, -0.00222619017586112, 1.4629883766174316, 0.8108606338500977, 0.9010099172592164, -0.3307216763496399, -0.4707276225