INSERT INTO `archived_documents` (`archived_id`, `team_id`, `title`, `abstract`, `authors`, `embedding`, `embedding_generated_at`, `academic_year`, `program`, `file_name`, `file_path`, `file_size`, `submitted_by`, `submitted_at`, `submission_status`) VALUES
(31, NULL, 'TRACKCSPC: A SMART CAMPUS VEHICLE TRACKING AND RESERVATION PLATFORM', 'This study presents TrackCSPC: A smart campus vehicle tracking and reservations platform developed for the Camarines Sur Polytechnic Colleges–General Services Unit (GSU) to address inefficiencies in manual vehicle reservation processes, including delays, inconsistent documentation, and limited monitoring. The system integrates a mobile application for submitting vehicle requests and tracking reservations in real time with a web-based administrative dashboard for approval, driver assignment, and GPS-based vehicle monitoring. A mixed-method research design was employed using surveys, interviews, and observations, while system evaluation involved functional testing, load testing, and User Acceptance Testing (UAT). Evaluation results yielded an overall mean score of 1.00, interpreted as Completely Functional, indicating high reliability, usability, and operational efficiency. The findings demonstrate that TrackCSPC improves workflow management, communication, and centralized vehicle monitoring, with only minor refinements identified for specific user groups. The study concludes that TrackCSPC effectively enhances campus transportation management through automated reservation workflows and real-time tracking and recommends continuous system maintenance, user training, and future enhancements such as AI-based scheduling and online payment integration. The study employed a mixed-method research design and evaluated the system through surveys, interviews, and direct observations. System performance was assessed using functional testing, load testing, and User Acceptance Testing (UAT). The evaluation results yielded an overall mean score of 1.00, interpreted as Completely Functional, demonstrating the system’s high reliability, usability, and operational efficiency.', 'Raxine D. Beriña, Debie S. Layron, Ronan Gabriel Paat', '[-0.9863309860229492, 1.262371063232422, -3.4927284717559814, -0.3058