INSERT INTO `archived_documents` (`archived_id`, `team_id`, `title`, `abstract`, `authors`, `embedding`, `embedding_generated_at`, `academic_year`, `program`, `file_name`, `file_path`, `file_size`, `submitted_by`, `submitted_at`, `submission_status`) VALUES
(37, NULL, 'WAMS: WEB-BASED APARTMENT MANAGEMENT SYSTEM FOR EFFICIENT TENANT AND FACILITY ADMINISTRATION', 'Manual apartment management in Nabua, Camarines Sur faces inefficiencies including paper-based records, delayed payment tracking, and slow maintenance handling across seven registered apartments, causing administrative errors and tenant dissatisfaction. This study developed the Web-Based Apartment Management System (WAMS) using Laravel framework and MySQL database to automate property management operations. Core modules include Apartment Unit Management, Applicant Management, Payment Billing System, and Maintenance Request handling with OTP verification, role-based access control, and PHPMailer automated notifications. The system was evaluated through black-box testing with 70 respondents (5 IT experts, 7 property owners, 58 tenants) using binary scoring (0-Failed, 1-Passed) across functional, load, and security dimensions. Results showed Functional Testing achieving 1.00 (Completely Functional), Load Testing scoring 0.96 (High Performance) under concurrent loads, and Security Testing reaching 1.00 (Fully Secure) against SQL injection, XSS attacks, and unauthorized access, yielding overall 0.99 effectiveness. WAMS successfully transformed manual operations into an automated web-based platform that eliminated paper-based delays, enhanced transparency, reduced administrative workload, and improved tenant satisfaction, proving reliable for Philippine apartment complexes with recommendations for mobile integration, analytics dashboards, automated scheduling, multi-language support, and two-factor authentication.', 'John Lhester B. Arco, Mark D. Decierra, LanderJade S. Gultiano', '[-0.25063320994377136, 1.5041266679763794, -3.1572115421295166, -0.6253281831741333, 0.04126209765672684, -1.0657553672790527, 0.6053293943405151, 0.7291393280029297, 0.5332971215248108, 0.033378347754478455, -0.4705914855003357, -0.08155101537704468, 1.6787681579589844, -0.06195364892482