INSERT INTO `archived_documents` (`archived_id`, `team_id`, `title`, `abstract`, `authors`, `embedding`, `embedding_generated_at`, `academic_year`, `program`, `file_name`, `file_path`, `file_size`, `submitted_by`, `submitted_at`, `submission_status`) VALUES
(39, NULL, 'UtiliCSPC: AN AUTOMATED VENUE RESERVATION AND RESOURCE MANAGEMENT SYSTEM FOR INSTITUTIONAL USE', 'This study presents UtiliCSPC: An automated web-based venue reservation and resource management system developed for Camarines Sur Polytechnic Colleges (CSPC) to address the inefficiencies of manual, paper-based procedures including scheduling conflicts, delayed approvals, inconsistent pricing, and poor resource tracking by providing a centralized platform for venue requests, real-time availability monitoring, automated cost computation, proof-of-payment submission, document generation, and administrative management, and which was evaluated through functional, usability, compatibility, and performance testing, achieving a mean score of 1.00 Completely Funtional for functional testing, 0.72 Highly Usable for usability, 0.88 Highly Compatible across devices and browsers, and 0.98 Optimized for performance, collectively demonstrating that UtiliCSPC significantly enhances operational efficiency, transparency, reliability, and accessibility in institutional venue reservation and resource management process. While also providing automated notifications and alerts to administrators and clients to ensure timely approvals and updates, reducing repetitive manual tasks and allowing staff to focus on higher-level administrative duties, integrating real-time data synchronization to maintain accurate inventory and venue availability, incorporating standardized document generation and cost estimation workflows to minimize human error, and receiving positive stakeholder feedback that confirms usability for non-technical users and supports faster adoption, thereby strengthening institutional governance, informed decision-making, and overall process sustainability.', 'Shella May G. Miday, Erlan Notorio, Abigail C. Villaueva', '[-0.8077829480171204, 1.9673428535461424, -3.003826379776001, -1.0755715370178225, 0.5830385684967041, -0.23181483149528503, 0.6747333407402039, 1.3278