INSERT INTO `archived_documents` (`archived_id`, `team_id`, `title`, `abstract`, `authors`, `embedding`, `embedding_generated_at`, `academic_year`, `program`, `file_name`, `file_path`, `file_size`, `submitted_by`, `submitted_at`, `submission_status`) VALUES
(41, NULL, 'A WEB-BASED BARANGAY INCIDENT REPORTING SYSTEM WITH INTEGRATED REPORT SUBMISSION TO PNP NABUA', 'This study presents the design and development of a Web-based Barangay Incident Reporting System with Integrated Report Submission to PNP Nabua. The system aims to improve the efficiency, accuracy, and security of incident documentation and reporting at the barangay level while ensuring timely coordination with the Philippine National Police (PNP). Traditional manual blotter recording and reporting processes are prone to delays, data inconsistencies, and limited accessibility, which can hinder effective incident management and law enforcement response. The developed system allows authorized barangay personnel to manage blotter records, mediation schedules, document uploads, and monthly reports, while enabling citizens to submit incident and e-blotter reports online. Submitted reports are subject to verification by barangay officials before being officially recorded and forwarded to the PNP Nabua for further action when necessary. The system implements role-based access control and encrypted passwords to safeguard sensitive information and ensure data privacy. To evaluate the system’s effectiveness, black-box testing, user acceptance, usability testing, and decision-based testing were conducted to assess functionality, ease of use, and compliance with user requirements.', 'Alexcirus A. Abagat, Jeremiah L. Belza, Mark Ronel L. Obrero', '[0.10811199247837068, 0.4629736542701721, -3.138322353363037, -0.9209845066070556, 1.532613754272461, -0.7305554151535034, -0.06446455419063568, -0.39931872487068176, -0.07974687218666077, -1.0369794368743896, -0.049874600023031235, -0.6195403337478638, 0.643706738948822, -0.2515450716018677, -0.21858182549476624, -1.656274914741516, -0.5689914226531982, -1.2540156841278076, -1.5752253532409668, 0.694583535194397, -0.2506236433982849, -0.7074921131134033, -1.5565444231033323, 0.10895855724811554, 2.2057628631591797, 0.6965590715