INSERT INTO `archived_documents` (`archived_id`, `team_id`, `title`, `abstract`, `authors`, `embedding`, `embedding_generated_at`, `academic_year`, `program`, `file_name`, `file_path`, `file_size`, `submitted_by`, `submitted_at`, `submission_status`) VALUES
(85, NULL, 'LOCKMAC: A WEB-BASED MANAGEMENT SYSTEM FOR MACLABORATORY INTEGRATING RFID', 'The Camarines Sur Polytechnic Colleges, College of Computer Studies Mac Laboratory relies on manual processes for managing attendance, access control, and resource allocation, leading to inefficiencies and security vulnerabilities. In response, the capstone project was developed to modernize and secure laboratory management through the integration of RFID technology. This system automates attendance logging and access control, enhancing record accuracy and security while streamlining administrative tasks. Using Extreme Programming (XP) methodology, the project incorporated continuous feedback and iterative testing to ensure user-centric design. A mixed-method approach gathered insights from 327 students, faculty, and IT experts, informing system requirements and effectiveness. Rigorous black box testing confirmed the system’s robustness, user alignment, and security resilience. These outcomes affirm LockMac’s readiness for deployment, highlighting its potential to significantly improve laboratory management and serve as a scalable model for other educational environments.', 'JOHN FRANCIS C. CARPO, MARYLIE L. REFEREZA', '[-0.1217421442270279, 0.4651108384132385, -2.960568428039551, -0.1708884835243225, 0.8888874053955078, -0.3838569521903992, 0.66654372215271, 0.29157769680023193, 0.6205410361289978, -0.29222020506858826, -0.15495307743549347, -0.8213276863098145, 1.5389516353607178, 0.8234790563583374, 0.24952904880046844, 0.312627375125885, 0.1804528534412384, 0.10877536982297896, -0.09809095412492752, -0.44509005546569824, 0.14247247576713562, -0.7502979040145874, -0.4077482521533966, -0.19376574456691745, 1.6281694173812866, 0.37472814321517944, 0.6940419673919678, -0.033486511558294296, -0.2494305968284607, 0.47449177503585815, 1.0563236474990845, -1.1177668571472168, 0.3797365427017212, -0.8562119007110596, -0.630754292011261, -1.6845545768737793, -0.090763658285141, 0.4263