INSERT INTO `archived_documents` (`archived_id`, `team_id`, `title`, `abstract`, `authors`, `embedding`, `embedding_generated_at`, `academic_year`, `program`, `file_name`, `file_path`, `file_size`, `submitted_by`, `submitted_at`, `submission_status`) VALUES
(93, NULL, 'CHRONOLOCK: RFID-ENABLED CLOUD SMART DOOR LOCK SYSTEM WITH REAL-TIME OCCUPANCY MONITORING', 'This study addresses the challenges of traditional access control and occupancy management in the ERP Laboratory, where inefficiencies, security risks, and manual processes hinder operational effectiveness. These challenges have long made it difficult to maintain safe and effective laboratory operations. The ChronoLock: RFID-Enabled Cloud Smart Door Lock System with Real-Time Occupancy Monitoring for CCS ERP LAB was developed as an innovative solution, integrating RFID technology and cloud-based monitoring to enhance security, automate access, and provide real-time occupancy data. Through comprehensive testing, the system demonstrated high functionality and reliability, proving its capability to meet the needs of modern laboratory management.', 'ARLAN B. IMPERIAL JR, ANDREY B. BABOL', '[-0.6340614557266235, 0.7523424625396729, -3.7922844886779785, -0.41430193185806274, 1.1134989261627195, -0.5790059566497803, 1.012324571609497, 0.28097984194755554, 0.5874135494232178, -0.5329519510269165, -0.3527155816555023, -0.1307886838912964, 1.1415143013000488, 0.5742384195327759, 0.6631597280502319, -0.12256989628076552, -0.03652007505297661, -0.003823396749794483, -0.5242725610733032, -0.8712385892868042, 0.6190533638000488, -0.655169665813446, -0.8956694006919861, -0.5494170784950256, 1.78436541557312, 0.8324536085128784, 0.7314957976341248, 0.4304388761520386, -0.13911297917366028, 0.3365230858325958, 1.341888427734375, -0.4580872058868408, -0.5814971923828125, -0.7500766515731812, -0.4369087219238281, -1.185481071472168, 0.1369199901819229, -0.08212481439113617, -0.28469061851501465, 0.9660849571228028, 1.1862969398498535, 0.7191424369812012, 1.2789361476898191, -0.5163390636444092, -0.22296199202537537, 0.2673948109149933, 1.137131929397583, 0.16485002636909485, 1.721569299697876, -0.11449681222438812, -0.03063073940575123, -0.4110395014286041, -0.443019837141037, 0.22