INSERT INTO `archived_documents` (`archived_id`, `team_id`, `title`, `abstract`, `authors`, `embedding`, `embedding_generated_at`, `academic_year`, `program`, `file_name`, `file_path`, `file_size`, `submitted_by`, `submitted_at`, `submission_status`) VALUES
(95, NULL, 'LOCKUP: A MOBILE BASED MANAGEMENT SYSTEM FOR SMART DOOR LOCK ENHANCING SECURITY IN MAC LABORATORY', 'The study focuses on developing a mobile-based management system designed to enhance the security and accessibility of the MAC Laboratory. Through this innovative system, instructors can efficiently unlock or lock the smart door using a mobile application. The system eliminates the need for physical keys by incorporating advanced security features like fingerprint authentication or a unique 4-digit PIN code. Additionally, it provides real- time updates on the laboratory’s status, allowing users to determine its availability at any given moment. One of the key features of this system is its integration of push notifications, ensuring that instructors receive timely alerts regarding the lab’s usage and security. The LockUp Mobile app also offers remote access control, enabling instructors to manage the smart door lock from anywhere. This user-friendly and secure system aims to streamline access management while addressing common challenges related to security, convenience, and operational efficiency in educational environments.', 'JOHN DEXTER P. ANI, JESSICA P. MATAYA, FREDERICK B. SALAZAR, JOSHUA M. SECUNDO', '[-0.9786983132362366, 1.0244061946868896, -3.2041969299316406, 0.2666683793067932, 0.6418200731277466, -0.14952552318572998, 0.8146410584449768, 0.7766984701156616, 0.9421669840812684, -0.1478123664855957, -0.4062012732028961, -0.6350733637809753, 0.9841684103012084, 0.6980830430984497, 0.4729679226875305, 0.013769589364528656, 0.6002426743507385, -0.7013591527938843, 0.010225027799606323, -0.515403151512146, 0.5189436674118042, -0.566419243812561, -0.7988947629928589, -0.3391357362270355, 1.5166490077972412, 0.4812196493148804, 0.8741487264633179, 0.690236508846283, -0.453146755695343, 0.9441133737564088, 0.6049532890319824, -1.1926767826080322, 0.30182576179504395, -0.6528927087783813, -1.1331291198730469, -1.439889907836914, 0.6174293160438538, -0