INSERT INTO `capstone_pre_proposals` (`id`, `team_id`, `duplication_check_id`, `slot`, `title`, `sdg_goals`, `research_agenda`, `problem_statement`, `proposed_solution`, `scope`, `limitations`, `sdm`, `tags`, `duplication_status`, `approved_status`, `rejection_reason`, `adviser_status`, `adviser_note`, `adviser_decided_at`, `submitted_at`, `retired_at`, `created_at`, `updated_at`) VALUES
(1, 1, 1, 1, 'CapsTrack: A Centralized Web-Based Capstone Project Management System at CSPC– College of Computer Studies', 'SDG 4 – Quality Education', '[\"Technology Development and Innovation\", \"e-Services\", \"Educational Management\", \"Applications and Systems Development\"]', 'The College of Computer Studies (CCS) of CSPC currently lacks a centralized web-based system for managing capstone projects, leading to inefficiencies, miscommunication, delayed outputs, and potential academic integrity issues.', 'Develop a web-based capstone management system for CSPC–CCS, providing secure student and instructor accounts, allowing students to apply for advisers, consultants, and grammarians, submit capstone outputs online, review and annotate submissions, manage schedules, track progress, and perform AI-based duplication checks.', 'The proposed web system will focus exclusively on capstone-related activities within CSPC–CCS, centralizing all processes to improve workflow efficiency and maintain academic integrity.', 'The system is limited to CSPC–CCS capstone projects only; duplication checking is restricted to archived prior studies and stored capstone outputs; internet access is required for the system to function; grading, evaluation, and final decisions remain the responsibility of instructors; the platform does not replace official academic record systems.', 'Agile Development Methodology', NULL, 'free', 1, NULL, NULL, NULL, NULL, '2026-09-08 02:26:15', '2026-09-15 00:40:29', '2026-09-08 02:19:10', '2026-09-15 00:40:29'),
(2, 1, 2, 2, 'CapsSys: Web-based Capstone Management System for CSPC CCS Sample sample sap shaha', 'SDG 4 – Quality Education', '[\"Technology Development and Innovation\", \"e-Services\", \"Educational Management\", \"Applications and Systems Development\"]', 'The College of Computer Studies (CCS) of CSPC currently lacks a centralized web-based system for managing capstone projects, leading to inefficiencies, miscommunication, delayed outputs, and potential academic integrity issues.', 'Develop a web-based capstone management system for CSPC–CCS, providing secure accounts for both students and instructors, allowing them to apply for advisers, consultants, and grammarians, submit capstone outputs online, review and annotate submissions, manage schedules, track progress, and perform duplication checks with AI.', 'The proposed web system will focus exclusively on capstone-related activities within CSPC–CCS, centralizing all processes to improve workflow efficiency and maintain academic integrity.', 'The system is limited to CSPC–CCS capstone projects only; duplication checking is restricted to archived prior studies and stored capstone outputs; internet access is required for the system to function; grading, evaluation, and final decisions remain the responsibility of instructors; the platform does not replace official academic record systems.', 'Agile Development Methodology', NULL, 'free', 1, NULL, NULL, NULL, NULL, '2026-09-08 02:26:15', '2026-09-15 00:40:29', '2026-09-08 02:20:23', '2026-09-15 00:40:29'),
(3, 3, 9, 1, 'MediTrack-MCH: A Digital Inventory and Patient Records Management System for a Lying-In Clinic Sample Sample', 'SDG 3 – Good Health and Well-being', '[\"Health Technologies\", \"Information Science\", \"Process Automation\", \"Smart Computing\"]', 'The current manual, paper-based records for managing patient information and medicine inventory increase the risk of lost, damaged, or incomplete records, inaccurate stock monitoring, and delayed identification of expired or low-stock medicines.', 'The project proposes the development of a web-based Integrated Patient Records and Medicine Inventory System for the Lying-In Clinic, including modules for patient records management, medicine inventory monitoring, expiring medicine notifications, low-Stock alerts, and user account management.', 'The system will include modules for patient records management (maternal & child health), medicine inventory management, expiring medicine notification system, low-Stock alerts and inventory reports, medicine issuance and usage tracking, user account management (admin, midwife, staff), data search, filtering, and report generation.', 'The system requires internet or local network connectivity; existing paper records must be manually encoded during initial implementation; the system is designed specifically for the Lying-In Clinic and does not cover hospital-wide integration.', 'Agile Development Methodology', NULL, 'contains_duplication', 0, NULL, NULL, NULL, NULL, '2026-09-13 01:57:35', NULL, '2026-09-13 01:54:00', '2026-09-13 01:57:35'),
(4, 3, 10, 2, 'PROJ-TRACK: An Integrated Monitoring and Automated Notification System for CSPC-PPFMS Nabua cAM SUR SAMPLE', 'SDG 9 – Industry, Innovation and Infrastructure', '[\"Process Automation\", \"Information Science\", \"Smart Computing\", \"Business Administration and Management\"]', 'The CSPC Office of the Director - PPFMS currently relies on manual, paper-based records to monitor infrastructure, leading to risks of lost documents and delayed reporting, and a lack of spatial visualization.', 'The project proposes a web-based system that centralizes project records and provides automated notifications, integrating the Google Maps API for geospatial mapping and area tracking.', 'Project & Contract Management; Geospatial Mapping & Area Tracking; Timeline & Progress Monitoring; Automated Alerts; Comprehensive Reporting; Document Archiving; AI Intelligence Engine', 'Connectivity; Data Entry; Integration; AI Accuracy; Geospatial Precision', 'Agile Development Methodology', NULL, 'contains_duplication', 0, NULL, NULL, NULL, NULL, NULL, NULL, '2026-09-13 01:57:25', '2026-09-13 01:57:25'),
(5, 6, 12, 1, 'Smart Parking Finder for the CSPC Campus', 'SDG 11 – Sustainable Cities and Communities', '[\"Applications and Systems Development\"]', 'Sample problem statement for Smart Parking Finder for the CSPC Campus.', 'A web-based system.', 'CSPC campus only.', 'Needs internet access.', 'Agile Development Methodology', NULL, 'free', 1, NULL, NULL, NULL, NULL, '2026-09-07 16:30:23', NULL, '2026-09-14 16:30:23', '2026-09-14 16:30:23'),
(6, 6, 13, 2, 'Barangay Clearance Request Tracker', 'SDG 11 – Sustainable Cities and Communities', '[\"Applications and Systems Development\"]', 'Sample problem statement for Barangay Clearance Request Tracker.', 'A web-based system.', 'CSPC campus only.', 'Needs internet access.', 'Agile Development Methodology', NULL, 'free', 0, NULL, NULL, NULL, NULL, '2026-09-07 16:30:23', NULL, '2026-09-14 16:30:23', '2026-09-14 16:30:23'),
(7, 7, 14, 1, 'Online Canteen Ordering with Queue Numbers', 'SDG 11 – Sustainable Cities and Communities', '[\"Applications and Systems Development\"]', 'Sample problem statement for Online Canteen Ordering with Queue Numbers.', 'A web-based system.', 'CSPC campus only.', 'Needs internet access.', 'Agile Development Methodology', NULL, 'free', 0, NULL, NULL, NULL, NULL, NULL, NULL, '2026-09-14 16:30:23', '2026-09-14 16:30:23'),
(8, 7, 15, 2, 'Barangay Clearance Request Tracker', 'SDG 11 – Sustainable Cities and Communities', '[\"Applications and Systems Development\"]', 'Sample problem statement for Barangay Clearance Request Tracker.', 'A web-based system.', 'CSPC campus only.', 'Needs internet access.', 'Agile Development Methodology', NULL, 'free', 0, NULL, NULL, NULL, NULL, NULL, NULL, '2026-09-14 16:30:23', '2026-09-14 16:30:23'),
(9, 1, 8, 3, 'CSPC SiteSense: Smart Facility Maintenance with AR-Assisted Location Guidance Sample Sample Sample', 'SDG 9 – Industry, Innovation and Infrastructure', '[\"Augmented Reality and Virtual Reality\", \"Smart Computing\", \"Process Automation\", \"Information Science\"]', 'CSPC relies on manual and informal reporting methods for campus-related problems, leading to delayed, incomplete, or misplaced reports, and difficulties in locating exact problem areas.', 'Develop a mobile-based Problem Reporting Application with AR Path Finder for real-time visual navigation, automated notifications, and status tracking.', 'Mobile Problem Reporting (Photo, Description, Location); AR Path Finder for Location Guidance; Report Categorization and Priority Level Assignment; Real-Time Status Tracking (Pending, Ongoing, Resolved); Automated Notifications and Alerts; Analytics Dashboard and Reports; User Account Management (Students, Staff, Maintenance).', 'AR navigation accuracy depends on device sensors and camera quality; Requires smartphone compatibility with AR features; Internet connection is required for real-time reporting and updates.', 'Agile Development Methodology', '[\"Mobile App\", \"AR / VR\", \"GIS / Mapping\"]', 'free', 1, NULL, 'approved', NULL, '2026-09-15 01:00:38', '2026-09-15 00:42:34', '2026-09-16 03:52:38', '2026-09-15 00:41:58', '2026-09-16 03:52:38'),
(10, 1, 17, 4, 'MediTrack-MCH: A Digital Inventory and Patient Records Management System for a Lying-In Clinic, Sample Sample', 'SDG 3 – Good Health and Well-being', '[\"Health Technologies\", \"Information Science\", \"Process Automation\", \"Smart Computing\"]', 'The current manual, paper-based records for managing patient information and medicine inventory increase the risk of lost, damaged, or incomplete records, inaccurate stock monitoring, and delayed identification of expired or low-stock medicines.', 'The project proposes the development of a web-based Integrated Patient Records and Medicine Inventory System for the Lying-In Clinic, including modules for patient records management, medicine inventory monitoring, expiring medicine notifications, low-Stock alerts, and user account management.', 'The system will include modules for patient records management (maternal & child health), medicine inventory management, expiring medicine notification system, low-Stock alerts and inventory reports, medicine issuance and usage tracking, user account management (admin, midwife, staff), data search, filtering, and report generation.', 'The system requires internet or local network connectivity; existing paper records must be manually encoded during initial implementation; the system is designed specifically for the Lying-In Clinic and does not cover hospital-wide integration.', 'Agile Development Methodology', '[\"Management System\"]', 'contains_duplication', 1, NULL, 'approved', NULL, '2026-09-16 03:56:45', '2026-09-16 03:56:28', NULL, '2026-09-16 03:56:20', '2026-09-16 03:56:45'),
(11, 8, 19, 1, 'CSPC SiteSense: Smart Facility Maintenance with AR-Assisted Location Guidance SAMPLE SAMPLE SAMPLE', 'SDG 9 – Industry, Innovation and Infrastructure', '[\"Augmented Reality and Virtual Reality\", \"Smart Computing\", \"Process Automation\", \"Information Science\"]', 'CSPC relies on manual and informal reporting methods for campus-related problems, leading to delayed, incomplete, or misplaced reports, and difficulties in locating exact problem areas.', 'Develop a mobile-based Problem Reporting Application with AR Path Finder for real-time location guidance, automated notifications, and analytics.', 'Mobile Problem Reporting (Photo, Description, Location); AR Path Finder for Location Guidance; Report Categorization and Priority Level Assignment; Real-Time Status Tracking (Pending, Ongoing, Resolved); Automated Notifications and Alerts; Analytics Dashboard and Reports; User Account Management (Students, Staff, Maintenance).', 'AR navigation accuracy depends on device sensors and camera quality; Requires smartphone compatibility with AR features; Internet connection is required for real-time reporting and updates.', 'Agile Development Methodology', '[\"Mobile App\", \"AR / VR\", \"GIS / Mapping\"]', 'contains_duplication', 1, NULL, NULL, NULL, NULL, '2026-09-17 01:44:36', '2026-09-17 06:41:13', '2026-09-17 01:42:34', '2026-09-17 06:41:13'),
(12, 8, 20, 2, 'PROJ-TRACK: An Integrated Monitoring and Automated Notification System for CSPC-PPFMS NABUA CAM SUR SAMPLE', 'SDG 9 – Industry, Innovation and Infrastructure', '[\"Process Automation\", \"Information Science\", \"Smart Computing\", \"Business Administration and Management\"]', 'The CSPC Office of the Director - PPFMS currently relies on manual, paper-based records to monitor infrastructure, leading to risks of lost documents and delayed reporting, and a lack of spatial visualization.', 'The project proposes a web-based system that centralizes project records and provides automated notifications, integrating the Google Maps API for geospatial mapping and area tracking.', 'Project & Contract Management; Geospatial Mapping & Area Tracking; Timeline & Progress Monitoring; Automated Alerts; Comprehensive Reporting; Document Archiving; AI Intelligence Engine', 'Connectivity; Data Entry; Integration; AI Accuracy; Geospatial Precision', 'Agile Development Methodology', '[\"Web-based\", \"Management System\", \"Decision Support System\", \"GIS / Mapping\"]', 'contains_duplication', 1, NULL, NULL, NULL, NULL, '2026-09-17 01:44:36', '2026-09-17 06:41:13', '2026-09-17 01:44:07', '2026-09-17 06:41:13');

