--
-- Table structure for table `grading_rubrics`
--

DROP TABLE IF EXISTS `grading_rubrics`;
CREATE TABLE IF NOT EXISTS `grading_rubrics` (
  `rubric_id` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
  `rubric_name` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `rubric_type` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `description` text COLLATE utf8mb4_unicode_ci,
  `total_points` decimal(6,2) NOT NULL DEFAULT '100.00',
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `is_archived` tinyint NOT NULL DEFAULT '0',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`rubric_id`)
) ENGINE=MyISAM AUTO_INCREMENT=13 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

--
-- Dumping data for table `grading_rubrics`
--

INSERT INTO `grading_rubrics` (`rubric_id`, `rubric_name`, `rubric_type`, `description`, `total_points`, `is_active`, `is_archived`, `created_at`, `updated_at`) VALUES
(10, 'Capstone Title Defense Evaluation', 'Title Defense', 'Assesses the readiness, clarity, and effectiveness of the team\'s presentation and defense during the capstone project\'s final evaluation stage.', 100.00, 1, 0, '2026-08-20 06:20:12', '2026-08-20 06:20:12'),
(11, 'Pre-Proposal Defense Rubric', 'Pre-Proposal Defense', 'Evaluates a capstone team\'s pre-proposal defense across manuscript delivery, topic quality and proposal merit, and proposal content and clarity.', 100.00, 1, 0, '2026-08-20 06:34:53', '2026-08-20 06:34:53'),
(12, 'Title Defense Rubric', 'Title Defense', 'Evaluates a capstone team\'s title defense across Chapters 1-3, grammar and spelling, oral examination/presentation, research instrument, and timeliness.', 100.00, 0, 1, '2026-08-27 06:41:08', '2026-09-13 07:35:53');

