--
-- Table structure for table `panel_grades`
--

DROP TABLE IF EXISTS `panel_grades`;
CREATE TABLE IF NOT EXISTS `panel_grades` (
  `grade_id` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
  `defense_id` bigint UNSIGNED NOT NULL,
  `expert_id` bigint UNSIGNED NOT NULL,
  `rubric_id` bigint UNSIGNED NOT NULL,
  `scores` json DEFAULT NULL,
  `total_score` decimal(6,2) DEFAULT NULL,
  `verdict` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `remarks` text COLLATE utf8mb4_unicode_ci,
  `status` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'draft',
  `submitted_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`grade_id`),
  UNIQUE KEY `panel_grades_defense_id_expert_id_unique` (`defense_id`,`expert_id`),
  KEY `panel_grades_expert_id_foreign` (`expert_id`),
  KEY `panel_grades_rubric_id_foreign` (`rubric_id`)
) ENGINE=MyISAM AUTO_INCREMENT=46 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

